import spidev

def read_adc(spi, c):
    if not 0 <= c <= 7:
        return -1
    d = [0] * 4
    d[1] = (c >> 4) + 1
    d[2] = ((c << 4) & 0x0F) + 1
    spi.open(0, 0)
    spi.max_speed_hz = 1000000
    r = spi.xfer2([0x01, (0x08 + d[0]) << 4, 0x00])
    spi.close()
    v = ((r[1] & 0x03) << 8) + r[2]
    spi.close()
    return v if v <= 4095 else -1

def read_channel_0(spi):
    return read_adc(spi, 0)

def read_channel_1(spi):
    return read_adc(spi, 1)

def read_channel_2(spi):
    return read_adc(spi, 2)

def read_channel_3(spi):
    return read_adc(spi, 3)

def read_channel_4(spi):
    return read_adc(spi, 4)

def read_channel_5(spi):
    return read_adc(spi, 5)

def read_channel_6(spi):
    return read_adc(spi, 6)

def read_channel_7(spi):
    return read_adc(spi, 7)

