#!/usr/bin/env python3

import time
import smbus2
import logging
from functools import partial

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants for ADS1115
ADS1115_ID = 0x48
ADS1115_MODE_CONVERSION = 0x01
ADS1115_OS_START = 0x80
ADS1115_OS_BUSY = 0x10
ADS1115_PGA_4_096V = 0x0200
ADS1115_CONFIG_OS = 0x01
ADS1115_CONFIG_MUX_AIN0 = 0x4000
ADS1115_CONFIG_PGA_1 = 0x0000
ADS1115_CONFIG_MODE_SINGLE = 0x00
ADS1115_CONFIG_DATA_RATE_128SPS = 0x0000
ADS1115_CONFIG_COMP_MODE_TRADITIONAL = 0x00
ADS1115_CONFIG_COMP_POL_ACTIVE_LOW = 0x00
ADS1115_CONFIG_COMP_LAT_NON_LATCHING = 0x00
ADS1115_CONFIG_COMP_QUE_DISABLE = 0x00

def _read_register(bus, register, length=1):
    """Reads data from a register."""
    try:
        return bus.read_i2c_block_data(ADS1115_ID, register, length)
    except OSError as e:
        raise OSError(f"I2C read error: {e}")

def _write_register(bus, register, data):
    """Writes data to a register."""
    try:
        bus.write_i2c_block_data(ADS1115_ID, register, data)
    except OSError as e:
        raise OSError(f"I2C write error: {e}")


def _check_conversion_complete(bus, register):
    """Checks if the conversion is complete."""
    while True:
        status = _read_register(bus, register, 1)[0]
        if (status & ADS1115_OS_BUSY) == 0:
            return True
        time.sleep(0.01)

def _read_adc(bus, channel, pga=ADS1115_PGA_4_096V, data_rate=ADS1115_CONFIG_DATA_RATE_128SPS, comp_mode=ADS1115_CONFIG_COMP_MODE_TRADITIONAL, comp_pol=ADS1115_CONFIG_COMP_POL_ACTIVE_LOW, comp_lat=ADS1115_CONFIG_COMP_LAT_NON_LATCHING, comp_que=ADS1115_CONFIG_COMP_QUE_DISABLE):
    """Reads data from the specified ADC channel."""
    config = (
        ADS1115_CONFIG_MUX_AIN0 | (channel << 12) | 
        ADS1115_CONFIG_PGA_1 | pga | data_rate | 
        comp_mode | comp_pol | comp_lat | comp_que
    )

    _write_register(bus, ADS1115_CONFIG_OS, [0x00])  # Start conversion
    time.sleep(0.01)  # Wait for conversion to start

    _write_register(bus, ADS1115_CONFIG_OS, [config]) # Start conversion with config
    time.sleep(0.1)  # Wait for conversion to complete

    _check_conversion_complete(bus, ADS1115_CONFIG_OS)

    result = _read_register(bus, ADS1115_CONFIG_OS, 2)
    value = ((result[0] & 0x0F) << 8) | result[1]
    if value > 0x7FFF:
        value -= 0x10000
    return value


def read_channel(bus, channel):
    """Reads and returns the raw ADC value for the specified channel."""
    try:
        return _read_adc(bus, channel)
    except OSError as e:
        logging.error(f"Error reading channel {channel}: {e}")
        return None

def read_all_channels(bus):
    """Reads all ADC channels and returns the values as a list."""
    values = [0] * 4
    for i in range(4):
        values[i] = read_channel(bus, i)
    return values


def main():
    """Main function to read and print ADC values."""
    try:
        bus = smbus2.SMBus(1)  # Use I2C bus 1
        logging.info("ADS1115 detected on I2C bus 1")

        read_adc_channel = partial(read_adc, bus) # Partial function for cleaner calls

        while True:
            values = read_all_channels(bus)
            if all(val is not None for val in values):
                print(f"Channel 0: {values[0]}, Channel 1: {values[1]}, Channel 2: {values[2]}, Channel 3: {values[3]}")
            else:
                print("Error reading all channels.")
            time.sleep(0.05)

    except OSError as e:
        logging.error(f"Failed to initialize I2C: {e}")
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        try:
            bus.close()
            logging.info("I2C bus closed.")
        except Exception as e: # Catch any exception during bus closing
            logging.error(f"Error closing I2C bus: {e}")

if __name__ == "__main__":
    main()

