import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# I2C setup
try:
    i2c = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"I2C Error: {e}")
    exit()

# ADS1115 setup
try:
    ads = ADS.ADS1115(i2c)
except Exception as e:
    print(f"ADS1115 Error: {e}")
    exit()

# Channel setup
channel_list = [AnalogIn(ads, i) for i in range(4)]

# Main loop
while True:
    try:
        print("| {0:>6} | {1:>6} | {2:>6} | {3:>6} |".format(*["Channel {}".format(i) for i in range(4)]))
        print("-" * 37)
        for channel in channel_list:
            try:
                value = channel.value
                print("| {0:>6} |".format(int(value)))
            except Exception as e:
                print("|     |".format())
        time.sleep(0.5)
    except KeyboardInterrupt:
        print("Exiting...")
        break
    except Exception as e:
        print(f"Error reading ADC values: {e}")

