import cv2
import time
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
FACE_CASCADE_PATH = cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'
CAMERA_INDEX = 0
WINDOW_NAME = "Real-time Face Detection"
QUIT_KEY = 'q'
FRAME_FORMAT = cv2.COLOR_RGB2BGR  # Ensure consistent format
HAAR_SCALE_FACTOR = 1.1
HAAR_MIN_NEIGHBORS = 5
HAAR_RECTANGLE_COLOR = (255, 0, 0)  # BGR format
HAAR_RECTANGLE_THICKNESS = 2


class GracefulKiller:
    """Handles SIGINT and SIGTERM signals for graceful exit."""

    kill_now = False

    def __init__(self):
        signal.signal(signal.SIGINT, self.exit_gracefully)
        signal.signal(signal.SIGTERM, self.exit_gracefully)

    def exit_gracefully(self, signum, frame):
        self.kill_now = True


class FaceDetector:
    """Detects faces in a given image or video stream."""

    def __init__(self, cascade_path):
        try:
            self.face_cascade = cv2.CascadeClassifier(cascade_path)
            if self.face_cascade.empty():
                raise IOError("Unable to load face cascade classifier")
        except Exception as e:
            logging.error(f"Error initializing FaceDetector: {e}")
            sys.exit(1)

    def detect_faces(self, image):
        """Detects faces in the given image."""
        gray_image = cv2.cvtColor(image, FRAME_FORMAT)
        return self.face_cascade.detectMultiScale(gray_image, HAAR_SCALE_FACTOR, HAAR_MIN_NEIGHBORS)

    def draw_rectangles(self, image, rectangles):
        """Draws rectangles around detected faces."""
        for (x, y, w, h) in rectangles:
            cv2.rectangle(image, (x, y), (x + w, y + h), HAAR_RECTANGLE_COLOR, HAAR_RECTANGLE_THICKNESS)


def initialize_camera(camera_index):
    """Initializes the camera."""
    try:
        capture = cv2.VideoCapture(camera_index)
        if not capture.isOpened():
            raise IOError(f"Cannot open camera {camera_index}")
        return capture
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        return None


def process_frame(frame, face_detector):
    """Processes a single frame, detects faces, and draws rectangles."""
    faces = face_detector.detect_faces(frame)
    face_detector.draw_rectangles(frame, faces)
    return frame


def main():
    """Main function for real-time face detection."""

    killer = GracefulKiller()
    face_detector = FaceDetector(FACE_CASCADE_PATH)
    camera = initialize_camera(CAMERA_INDEX)

    if camera is None:
        logging.error("Camera initialization failed. Exiting.")
        return

    try:
        while not killer.kill_now:
            ret, frame = camera.read()
            if not ret:
                logging.warning("Failed to grab frame. Continuing anyway.")
                continue

            processed_frame = process_frame(frame, face_detector)

            cv2.imshow(WINDOW_NAME, processed_frame)

            if cv2.waitKey(1) & 0xFF == ord(QUIT_KEY):
                break

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Releasing resources and exiting.")
        if camera is not None:
            camera.release()
        cv2.destroyAllWindows()


if __name__ == "__main__":
    main()

