import io
import logging
import threading
import time
import signal
import sys
from typing import Callable, Optional

import cv2
import numpy as np
from picamera2 import Picamera2, MappedArray
from picamera2.encoders import H264Encoder, Quality
from picamera2.outputs import FfmpegOutput

from general import WebSocketHandler  # Assuming this module exists

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

FrameBuffer = io.BytesIO
MotionBuffer = io.BytesIO


def _ensure_frame_buffer(frame_buffer: FrameBuffer) -> FrameBuffer:
    """Pads the frame buffer to a multiple of 16 bytes, ensuring it can hold a single JPEG frame."""
    while len(frame_buffer.getbuffer()) % 16 != 0:
        byte_to_write = bytes([0])
        frame_buffer.write(byte_to_write)
    return frame_buffer


def _write_jpeg_data(buffer: FrameBuffer, data: bytes) -> int:
    """Writes JPEG data to the frame buffer and returns the number of bytes written."""
    buffer.write(data)
    return len(data)


def _decode_jpeg_data(buffer: FrameBuffer) -> Optional[np.ndarray]:
    """Decodes JPEG data from the frame buffer and returns a NumPy array."""
    try:
        from PIL import Image  # Import here to avoid dependency if not needed

        img = Image.open(buffer)
        return np.array(img)
    except (IOError, OSError, ImportError) as e:
        logger.error(f"Error decoding JPEG data: {e}")
        return None
    except Exception as e:
        logger.error(f"Unexpected error during JPEG decoding: {e}")
        return None


def _encode_frame(encoder: H264Encoder, frame: np.ndarray) -> bytes:
    """Encodes a frame using the given H264 encoder."""
    return encoder.encode(frame)


def _write_frame_data(output: FfmpegOutput, frame_data: bytes) -> None:
    """Writes encoded frame data to the output."""
    output.write(frame_data)


def _broadcast_frame(websocket_handler: WebSocketHandler, frame_data: bytes) -> None:
    """Broadcasts frame data over WebSocket if connections exist."""
    if websocket_handler.has_connections():
        websocket_handler.broadcast(frame_data)


class CameraStreamHandler:
    """Handles capturing and streaming camera frames."""

    def __init__(self, picam2: Picamera2, frame_buffer: FrameBuffer, motion_buffer: MotionBuffer, motion_detection_function: Callable[[np.ndarray, np.ndarray], None], *args, **kwargs):
        """Initializes the CameraStreamHandler."""
        self.picam2 = picam2
