import serial
import time
import csv
import os

# Define serial port and baud rate
SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200

# Define CSV file name
CSV_FILE = 'temperature_log.csv'

def initialize_serial(port, baud):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baud, timeout=1)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_temperature(serial_connection):
    """Reads temperature data from the serial port."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            temperature_celsius = float(line)
            temperature_fahrenheit = temperature_celsius * 9/5 + 32
            return temperature_fahrenheit
        return None
    except ValueError:
        print("Warning: Malformed data received from sensor.")
        return None

def log_temperature(csv_file, temperature):
    """Logs the temperature data to a CSV file."""
    try:
        with open(csv_file, 'a', newline='') as csvfile:
            csv_writer = csv.writer(csvfile)
            csv_writer.writerow([time.strftime('%Y-%m-%d %H:%M:%S'), temperature])
    except IOError as e:
        print(f"Error writing to CSV file: {e}")

