import serial
import time
import RPi.GPIO as GPIO
import Adafruit_DHT

# Define constants
SERIAL_PORT = '/dev/ttyS0'  # UART port on Raspberry Pi (e.g., /dev/ttyS0 or /dev/ttyAMA0)
BAUD_RATE = 9600
DHT_SENSOR = Adafruit_DHT.DHT22
DHT_PIN = 4  # GPIO pin connected to the DHT22 data pin

# Initialize serial communication
try:
    serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
except serial.SerialException as e:
    print(f"Error opening serial port: {e}")
    exit(1)

# Setup GPIO using BCM numbering
GPIO.setmode(GPIO.BCM)

def read_temperature():
    """Reads temperature from DHT22 sensor."""
    try:
        humidity, temperature = Adafruit_DHT.read_retry(DHT_SENSOR, DHT_PIN)
        if temperature is not None:
            return round(temperature, 2)
        else:
            print("Failed to retrieve temperature from DHT22 sensor.")
            return None
    except RuntimeError as e:
        print(f"DHT Sensor Error: {e}")
        return None

def transmit_data(temperature):
    """Transmits temperature data over UART."""
    if temperature is not None:
        try:
            serial_connection.write(f'Temperature: {temperature}.00\n'.encode('utf-8'))
            print(f"Sent: Temperature = {temperature} C")
        except serial.SerialException as e:
            print(f"Error writing to serial port: {e}")

def main():
    """Main function to read and transmit temperature data."""
    try:
        while True:
            temperature = read_temperature()
            transmit_data(temperature)
            time.sleep(1)  # Wait for 1 second
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        # Clean up resources
        serial_connection.close()
        GPIO.cleanup()
        print("Serial port closed and GPIO cleaned up.")

if __name__ == "__main__":
    main()

