import sys
import subprocess
import time
import threading
import logging
import os

from doG import doG  # Assuming this is the module for interacting with the DOG device
from setProxies import setProxies  # Assuming these are modules for handling proxies

logger = logging.getLogger(__name__)

def initialize_logging():
    """Configures the logging system."""
    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


def run_command(command):
    """Runs a shell command and returns the output.

    Args:
        command (str): The command to execute.

    Returns:
        str or None: The command's stdout if successful, None otherwise.
    """
    try:
        process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        stdout, stderr = process.communicate()

        if process.returncode != 0:
            logger.error(f"Command '{command}' failed with return code {process.returncode}."
                         f"Stderr: {stderr}")
            return None

        return stdout
    except Exception as e:
        logger.error(f"Error running command '{command}': {e}")
        return None


def get_yes_no_input(prompt, allow_numeric=False):
    """Prompts the user for a yes/no answer.

    Args:
        prompt (str): The prompt to display to the user.
        allow_numeric (bool, optional): If True, allows numeric input. Defaults to False.

    Returns:
        str or None: The user's answer if valid, None otherwise.
    """
    while True:
        answer = input(prompt + ' ').strip().lower()
        if answer in ('y', 'yes'):
            return 'y'
        elif answer in ('n', 'no'):
            return 'n'
        elif allow_numeric:
            return answer
        else:
            print('Answer Y or N')


def display_help(parent, child):
    """Displays help information about a command.

    Args:
        parent : p
        child : c
    """
    help_info = doG.display_help(child)
    if help_info:
        print(help_info)
        if get_yes_no_input(f"{child} : Help (yes/no)"):
            parent.children[child] = {'help_given': True, 'help_args': help_info}
    else:
        print("No help available for this command.")

def auto_write_file(filename):
    """Automatically writes data to a file if the filename changes."""
    if os.path.exists(filename):
        try:
            with open(filename, 'a') as f:
                for data in doG.receive():
                    f.write(data + '\n')
        except Exception as e:
            logger.error(f"Error writing to file '{filename}': {e}")




def start_logging(filename, start_with_numbering=False, increment_per_file=1):
    """Starts logging data to a file.

    Args:
        filename (str): The name of the file to log to.
        start_with_numbering (bool, optional): If True, starts numbering records. Defaults to False.
        increment_per_file (int, optional): The increment value for numbering. Defaults to 1.
    """

    if start_with_numbering:
        if not os.path.exists(filename):
            try:
                with open(filename, 'w') as f:
                    f.write('1\n')
            except Exception as e:
                logger.error(f"Error creating/initializing file '{filename}': {e}")
                return

        number = int(open(filename, 'r').readline()) + increment_per_file - 1

    else:
        number = 1

    logger.info(f"Starting logging to '{filename}'. Numbering records, starting with '{number}'.")

    try:
        while True:
            try:
                with open(filename, 'a') as f:
                    for data in doG.receive():
                        f.write(str(number) + ': ' + data + '\n')
                        number += increment_per_file
                        if number > doG.maxRecords + 1:
                            number = 1
                            logger.info(f"Reached maximum record number '{doG.maxRecords}' for logging to '{filename}'.")
            except Exception as e:
                logger.error(f"Error writing to file '{filename}': {e}")
                time.sleep(1)  # Prevent excessive error logging
                continue

            time.sleep(0.1)  # Add a small delay to reduce CPU usage

    except KeyboardInterrupt:
        logger.info(f"Stopping logging to '{filename}'.")


def handle_command(parent, child):
    """Handles a command input by the user."""
    cmd = child.get_command()

    if not cmd:
        return

    subcommand = cmd.split()[1]

    if subcommand == 'help':
        display_help(parent, child)
    elif subcommand == 'start':
        args = cmd.split()[2:]
        if len(args) == 1:
            filename = args[0]
        else:
            filename = ' '.join(args[1:])
            logger.warning(f" 'start' command requires only one filename, ignoring extra options: {filename}")

        if os.path.exists(filename):
            start_logging(filename, start_with_numbering=True, increment_per_file=1)
        else:
            logger.error(f"File '{filename}' does not exist.")
            parent.send("Error: File not found.")

    elif subcommand == 'write':
        args = cmd.split()[2:]
        if len(args) == 1:
            filename = args[0]
        else:
            filename = ' '.join(args[1:])
            logger.warning(f" 'write' command requires only one filename, ignoring extra options: {filename}")

        try:
            with open(filename, 'a') as f:
                for data in doG.receive():
                    f.write(data + '\n')
            logger.info(f"Wrote data to file '{filename}'.")

        except Exception as e:
            logger.error(f"Error writing to file '{filename}': {e}")
            parent.send("Error: Could not write to file.")

    elif subcommand == 'display':
        if doG.maxRecords > 0:
            try:
                with open('record.txt', 'r') as f:
                    lines = f.readlines()
            except Exception as e:
                logger.error(f"Error opening 'record.txt': {e}")
                parent.send("Error: Could not open record file.")
                return

            if doG.maxRecords > len(lines):
                logger.info(f"Record file '{record_file}' is full. Waiting for more data.")
                parent.send("File is full.")
                return

            for line in lines:
                print(line.strip())

    elif subcommand == 'exit':
        logger.info("Exiting on DOG side.")
        parent.send("Exit")
        parent.stop()  # Stop the DOG's API call loop
        sys.exit()

    else:
        logger.warning(f"Unknown subcommand: '{subcommand}'.")

class DogControl:
    """A class to manage DOG's API calls and user interaction."""
    dog = None
    running = False
    file_name = None
    thread = None

    def __init__(self, proxies=None, no_proxy=None):
