import requests
import time

# Define the GPIO pin connected to the voltage sensor
VOLTAGE_SENSOR_PIN = 17

# Define the URL to send alerts to
ALERT_ENDPOINT = 'http://example.com/alert'

# Configure GPIO settings
GPIO.setmode(GPIO.BCM)
GPIO.setup(VOLTAGE_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def check_power_status():
    """Checks the power status based on the voltage sensor pin."""
    return GPIO.input(VOLTAGE_SENSOR_PIN) == GPIO.LOW

def send_power_failure_alert():
    """Sends an alert to the specified endpoint."""
    try:
        requests.post(ALERT_ENDPOINT, json={'alert': 'Power failure detected'}, timeout=5)
    except requests.RequestException as e:
        print(f"Error sending alert: {e}")

def main_loop():
    """Main loop to continuously monitor power status."""
    try:
        while True:
            if check_power_status():
                print('Power failure detected!')
                send_power_failure_alert()
            else:
                print('Power is present')
            time.sleep(1)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main_loop()

