    def process_message(self, message: dict):
        """Processes a received message and calls the appropriate callbacks."""
        channel = message.get('channel')
        if channel in self.subscriptions:
            for info in self.subscriptions[channel]:
                callback = info['callback']
                args = info['args']
                kwargs = info['kwargs']
                try:
                    callback(json.loads(message['data']), *args, **kwargs)
                except (KeyError, TypeError) as e:
                    logger.error(f"Callback error for channel {channel}: {e}, message: {message}")



class PIDHandler:
    """
    Manages PID control and error output.
    """

    def __init__(self, logger: logging.Logger, config: dict, pwm_pin: int = 12, error_pin: int = 10):
        """
        Initializes the PIDHandler.

        Args:
            logger (logging.Logger): Logger instance for logging.
            config (dict): Configuration dictionary.
            pwm_pin (int): GPIO pin for PWM output.
            error_pin (int): GPIO pin for error output.
        """
        self.logger = logger
        self.config = config
        self.pwm_pin = pwm_pin
        self.error_pin = error_pin
        self.pwm = None
        self.error = None
        self.last_msg = time.time()
        self.watchdog_timeout = 20  # seconds

        GPIO.setmode(GPIO.BOARD)

        if self.error_pin in config.get('gpio', {}):
            GPIO.setup(self.error_pin, GPIO.OUT)
            self.error = GPIO.PWM(self.error_pin, 1000)
            self.error.start(0)

        if self.pwm_pin in config.get('gpio', {}):
            GPIO.setup(self.pwm_pin, GPIO.OUT)
            self.pwm = GPIO.PWM(self.pwm_pin, 1000)
            self.pwm.start(0)

        self.pids = {
            'PID': {'p': 1.0, 'i': 0.0, 'd': 0.0},
            'PID_DAC': {'p': 0.0, 'i': 0.0, 'd': 0.0}
        }

        self.subscriber_socket = None
        self.subscriber_thread = None
        self.subscriber_running = False

        self.subscription_handler = SubscriptionHandler(logger)


    def connect_subscriber(self, subscriber_socket: zmq.Socket):
        """Connects the handler to a subscriber socket."""
        self.subscriber_socket = subscriber_socket
        self.subscription_handler.connect(self.subscriber_socket)


    def subscribe(self, callback: Callable[[dict], None], *args, **kwargs):
        """Subscribes to data streams using the subscription handler."""
        channel = type(callback).__name__
        self.subscription_handler.handle_subscription(channel, callback, *args, **kwargs)


    def unsubscribe(self, channel: str):
        """Unsubscribes from a specific channel."""
        self.subscription_handler.handle_unsubscription(channel)

    def update_callback(self, channel: str, callback: Callable[[dict], None], *args, **kwargs):
        """Updates a callback function for a specific channel."""
        self.subscription_handler.handle_update_callback(channel, callback, *args, **kwargs)

    def remove_all_callbacks(self, channel: str):
        """Removes all callbacks for a specific channel."""
        self.subscription_handler.handle_remove_all_callbacks(channel)

    def handle_error(self, error_message: str):
        """Handles errors by setting the error output."""
        self.last_msg = time.time()
        self.logger.error(error_message)
        if self.error:
            self.error.ChangeDutyCycle(5)  # Set to 5% error
        if self.pwm:
            self.pwm.ChangeDutyCycle(50)  # Set to 50% error

    def reset_error(self, value: Union[int, float]):
        """Resets the error output."""
        if self.error:
            self.error.ChangeDutyCycle(0)
            if isinstance(value, (int, float)):
                self.pwm.ChangeDutyCycle(value)
            else:
                self.pwm.stop()
                self.pwm = None
                self.error.stop()
                self.error = None

    def watchdog(self):
        """Handles the watchdog timer."""
        if time.time() - self.last_msg > self.watchdog_timeout:
            self.logger.error("Watchdog timeout!")
            self.handle_error("Watchdog timeout!")
        else:
            if self.pwm:
                self.pwm.ChangeDutyCycle(50)
            if self.error:
                self.error.ChangeDutyCycle(0)


    def run(self):
        """Runs the main loop for the PID handler."""
        self.subscriber_running = True
        try:
            while self.subscriber_running:
                self.watchdog()
                if self.subscriber_socket is not None:
                    try:
                        message = self.subscriber_socket.recv()  # Non-blocking receive
                        self.process_message(message)
                        self.last_msg = time.time()
                    except zmq.ZMQError as e:
                        if e.errno == zmq.EAGAIN:
                            pass # No data available, continue looping
                        else:
                            self.logger.error(f"ZMQError: {e}")
                            self.handle_error(f"ZMQError: {e}")
                            break # Exit loop on persistent ZMQError
                    except Exception as e:
                        self.logger.error(f"Error processing message: {e}")
                        self.handle_error(f"Error processing message: {e}")
                        break # Exit loop on other exceptions
                time.sleep(0.1) # Prevent excessive CPU usage
        finally:
            self.cleanup()

    def cleanup(self):
        """Cleans up GPIO resources."""
        self.logger.info("Cleaning up GPIO...")
        if self.pwm:
            self.pwm.stop()
        if self.error:
            self.error.stop()
        GPIO.cleanup()


class GenericHandler:
    """
    A generic handler that can execute a user-defined function with arguments
    received from a ZeroMQ socket.
    """

    def __init__(self, logger: logging.Logger, config: dict, monitor_url: str = None):
        """
        Initializes the GenericHandler.

        Args:
            logger (logging.Logger): Logger instance for logging.
            config (dict): Configuration dictionary.
            monitor_url (str): URL for the monitoring service.
        """
        self.logger = logger
        self.config = config
        self.monitor_url = monitor_url

        if self.monitor_url:
            self._update_monitor()  # Initial monitoring update


    def _update_monitor(self):
        """Updates the monitoring service with the current configuration information."""
        if not self.monitor_url:
            return

        data = {'config': self.config}
        try:
            requests.post(self.monitor_url, json=data)
        except requests.exceptions.RequestException as e:
            logger.error(f"Failed to update monitor: {e}")



    def handle_message(self, socket: zmq.Socket, tag: str):
        """
        Processes a message by executing a user-defined function.

        Args:
            socket (zmq.Socket): The ZeroMQ socket to receive data from.
            tag (str): A tag associated with the message.
        """
        try:
            data = socket.recv()  # Receive data as a string
            data = json.loads(data) # Parse as JSON
            func_name = data.get('function')
            args = data.get('args')
            kwargs = data.get('kwargs')

            if func_name in self.config.get('functions',()):
                func = self.config['functions'][func_name]
                if callable(func):
                    try:
                        result = func(**kwargs, *args)
                        if result is not None:
                            logger.info(f"Executed function: {func_name} with result: {result}")
                            if self.monitor_url:
                                try:
                                    requests.post(self.monitor_url, json={'status': 'ok'})
                                except requests.exceptions.RequestException as e:
                                    logger.error(f"Failed to send OK status: {e}")
                            return result
                    except Exception as e:
                        logger.error(f"Error executing function {func_name}: {e}")
                        if self.monitor_url:
                            try:
                                requests.post(self.monitor_url, json={'status': 'error', 'message': str(e)})
                            except requests.exceptions.RequestException as ce:
                                logger.error(f"Failed to send error status: {ce}")
                else:
                    logger.warning(f"Function {func_name} is not callable.")
        except (json.JSONDecodeError, KeyError, IndexError) as e:
            logger.error(f"Error processing message: {e}")
        except zmq.ZMQError as e:
            if e.errno == zmq.EAGAIN:
                pass # No data available, continue looping
            else:
                logger.error(f"ZMQError: {e}")
        except Exception as e:
            logger.error(f"Unexpected error: {e}")



class Server:
    """
    A server that manages ZeroMQ sockets and handles client connections.
    """

    def __init__(self, logger: logging.Logger, config_file: str = None):
        """
        Initializes the Server.

        Args:
            logger (logging.Logger): Logger instance for logging.
            config_file (str): Path to a configuration file.
        """
        self.logger = logger
        self.sockets: List[zmq.Socket] = []
        self.subscriber_count: int = 0
        self.config = {}

        if config_file:
            try:
                with open(config_file, 'r') as f:
                    self.config = json.load(f)
            except (FileNotFoundError, json.JSONDecodeError) as e:
                logger.error(f"Error loading configuration file: {e}")
                self.config = {}

        self.subscriber_socket_count = self.config.get('subscriber_socket_count', 1)
        self.subscriber_socket_ids = [zmq.Socket(self).socket_id for _ in range(self.subscriber_socket_count)]
        self.subscriber_threads = []


    def _create_sockets(self):
        """Creates and connects the ZeroMQ sockets."""
        import contextlib

        with contextlib.suppress(OSError):
            self.sockets.append(zmq.Socket(zmq.POLLIN))
            self.sockets.append(zmq.Socket(zmq.POLLIN))
            self.sockets.append(zmq.Socket(zmq.POLLIN))
            self.sockets.append(zmq.Socket(zmq.POLLIN))

            for i, socket in enumerate(self.sockets):
                socket.setsockopt(zmq.LINGER, 0)
                socket.setsockopt(zmq.TCP_LINGER, 0)
                logger.info(f"Created socket {i}: {socket}")

    def handle_client(self, socket: zmq.Socket):
        """
        Handles a client connection by creating a new subscriber thread.

        Args:
            socket (zmq.Socket): The client socket.
        """
        socket_id = socket.getsockopt(zmq.ZMQ_ID)
        if socket_id not in self.subscriber_socket_ids:
            self.subscriber_socket_ids.append(socket_id)
            self.subscriber_count += 1

        self.subscriber_threads.append(
            threading.Thread(target=self._handle_subscriber, args=(socket, socket_id))
        )
        self.subscriber_threads[-1].start()


    def _handle_subscriber(self, socket: zmq.Socket, socket_id: int):
        """
        Handles a subscriber, receiving and processing messages.

        Args:
            socket (zmq.Socket): The subscriber socket.
            socket_id (int): The socket ID.
        """
        logger.info(f"Subscriber (ID: {socket_id}) connected.")
        self.subscription_handler.subscribe(socket, None) # Handle all messages

        try:
            while self.subscriber_running or self.subscriber_count > 0: # Check if main loop is still running
                try:
                    self.handle_message(socket, socket_id)
                except zmq.ZMQError as e:
                    if e.errno == zmq.EAGAIN:
                        pass # No data available, continue looping
                    else:
                        raise # Re-raise the exception to be handled in the main loop
                except Exception as e:
                    logger.error(f"Error in subscriber {socket_id}: {e}")
                    break # Exit the subscriber loop if an error occurs
        finally:
            logger.info(f"Subscriber (ID: {socket_id}) disconnected.")
            self.subscriber_count -= 1
            self.subscriber_threads.remove(self.subscriber_threads[-1])
            if self.subscriber_count == 0:
                self.subscriber_threads.pop()  # Remove the last thread if no more connections


    def run(self):
        """Runs the server, creating sockets and accepting client connections."""
        self._create_sockets()

        signal.signal(signal.SIGINT, lambda *args: sys.exit(0))
        signal.signal(signal.SIGTERM, lambda *args: self.shutdown())

        logger.info("Server started. Waiting for connections...")
        try:
            for i, socket in enumerate(self.sockets):
                socket.setsockopt(zmq.LINGER, 0)
                socket.setsockopt(zmq.TCP_LINGER, 0)
                socket.send(i, zmq.SNDMORE)  # Set ID
                self.handle_client(socket)
            while self.subscriber_count > 0:
                time.sleep(1)
        except OSError as e:
            logger.error(f"OS error: {e}")
        except Exception as e:
            logger.error(f"Unexpected error in server: {e}")
        finally:
            self.shutdown()


    def shutdown(self):
        """Shuts down the server, closing sockets and threads."""
        self.subscriber_running = False
        for socket in self.sockets:
            try:
                socket.close()
                logger.info(f"Closed socket.")
            except Exception as e:
                logger.error(f"Error closing socket: {e}")

        for thread in self.subscriber_threads:
            try:
                thread.join(timeout=5)
                if thread.is_alive():
                    logger.warning(f"Subscriber thread did not terminate in time. Joining anyway.")
            except Exception as e:
                logger.error(f"Error joining thread: {e}")


if __name__ == '__main__':
    server = Server(logger='run')
    server.run()

