import time
import board
import busio
import adafruit_fingerprint

# Define constants for I2C and fingerprint sensor
I2C_SCL_PIN = board.SCL
I2C_SDA_PIN = board.SDA
FINGERPRINT_ID = 1
CONFIDENCE_THRESHOLD = 60

def initialize_fingerprint_sensor():
    """Initializes the I2C bus and the fingerprint sensor."""
    try:
        i2c_bus = busio.I2C(I2C_SCL_PIN, I2C_SDA_PIN)
        fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
        return i2c_bus, fingerprint_sensor
    except Exception as e:
        print(f"Error initializing I2C or fingerprint sensor: {e}")
        return None, None

def get_fingerprint_image(fingerprint_sensor):
    """Captures a fingerprint image from the sensor."""
    try:
        print("Waiting for finger...")
        while fingerprint_sensor.get_image() != adafruit_fingerprint.OK:
            pass
        return True
    except Exception as e:
        print(f"Error capturing fingerprint image: {e}")
        return False

def convert_image_to_template(fingerprint_sensor):
    """Converts the fingerprint image to a template."""
    try:
        print("Creating template...")
        if fingerprint_sensor.image_2_tz(1) != adafruit_fingerprint.OK:
            return None
        return fingerprint_sensor.finger_search()
    except Exception as e:
        print(f"Error converting image to template: {e}")
        return None

def search_fingerprint_database(fingerprint_sensor, template):
    """Searches the fingerprint database for a match."""
    try:
        print("Searching database...")
        if fingerprint_sensor.finger_search(template) != adafruit_fingerprint.OK:
            return False
        return True
    except Exception as e:
        print(f"Error searching fingerprint database: {e}")
        return False

def authenticate_user(fingerprint_sensor, template):
    """Authenticates the user based on the fingerprint template."""
    try:
        print("Authenticating...")
        if fingerprint_sensor.finger_check(template) != adafruit_fingerprint.OK:
            return False
        print(f"User authenticated. Confidence: {fingerprint_sensor.finger_conf} {CONFIDENCE_THRESHOLD}%")
        return True
    except Exception as e:
        print(f"Error authenticating user: {e}")
        return False

def main():
    """Main function to handle fingerprint authentication."""
    i2c_bus, fingerprint_sensor = initialize_fingerprint_sensor()

    if i2c_bus is None or fingerprint_sensor is None:
        print("Failed to initialize fingerprint sensor. Exiting.")
        return

    try:
        while True:
            if get_fingerprint_image(fingerprint_sensor):
                template = convert_image_to_template(fingerprint_sensor)
                if template:
                    if search_fingerprint_database(fingerprint_sensor, template):
                        if authenticate_user(fingerprint_sensor, template):
                            print("Access Granted")
                    else:
                        print("Access Denied")
            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")

    finally:
        if i2c_bus:
            i2c_bus.deinit()
            print("I2C bus deinitialized.")
        print("Program finished.")

if __name__ == "__main__":
    main()

