import time
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# Configuration constants
LED_PIN = 18
PWM_FREQUENCY = 1000
I2C_SCL = board.SCL
I2C_SDA = board.SDA
TSL2561_ADDRESS = 0x29

# Initialize I2C bus
def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(I2C_SCL, I2C_SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

# Initialize the TSL2561 light sensor
def initialize_light_sensor(i2c_bus):
    """Initializes the TSL2561 light sensor."""
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c_bus, address=TSL2561_ADDRESS)
        sensor.gain = 'auto'
        return sensor
    except Exception as e:
        print(f"Error initializing TSL2561: {e}")
        return None

# Set up GPIO for LED control
def setup_led(pin):
    """Sets up the GPIO pin for PWM control."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)
    return GPIO.PWM(pin, PWM_FREQUENCY)

# Main function to control the LED brightness based on light sensor readings
def main():
    """Main function to read light sensor data and control LED brightness."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        return

    led_pwm = setup_led(LED_PIN)

    try:
        while True:
            try:
                light_level = light_sensor.lux
                if light_level is not None:
                    # Adjust LED brightness based on light level
                    led_pwm.ChangeDutyCycle(light_level)
                else:
                    print("Error reading light sensor data.")
            except Exception as e:
                print(f"An error occurred: {e}")

            time.sleep(1)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        # Cleanup resources
        led_pwm.stop()
        GPIO.cleanup()
        if i2c_bus:
            i2c_bus.deinit()

if __name__ == "__main__":
    main()

