    fan = GPIO.PWM(FAN_PIN, 25000)  # 25kHz frequency
    fan.start(0)  # Start with 0% duty cycle (fan off)
except Exception as e:
    print(f"Error initializing hardware PWM: {e}")
    fan = None  # Indicate that hardware PWM is not available

# Function to set the fan speed
def set_fan_speed(speed_percent):
    """Sets the fan speed as a percentage."""
    if fan:
        try:
            fan.ChangeDutyCycle(speed_percent)
            print(f"Fan speed set to: {speed_percent}%")
        except Exception as e:
            print(f"Error setting fan speed: {e}")
    else:
        print("Hardware PWM not available.  Using software PWM.")

# Main program loop
try:
    while True:
        # Prompt the user for fan speed input
        user_input = input("Enter fan speed (0-100, or 'q' to quit): ")

        # Check if the user wants to quit
        if user_input.lower() == 'q':
            break

        # Validate user input
        try:
            fan_speed = float(user_input)
            if 0 <= fan_speed <= 100:
