# A simple program to read light levels from a BH1750 sensor on Raspberry Pi.
# Designed for a kids coding lesson.

import time
import board
import busio
import adafruit_bh1750

# Define the I2C bus and sensor address
I2C_BUS = 1
SENSOR_ADDRESS = 0x23  # Default address for BH1750

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initializes the BH1750 light sensor."""
    try:
        sensor = adafruit_bh1750.BH1750(i2c_bus)
        return sensor
    except Exception as e:
        print(f"Error initializing sensor: {e}")
        return None

def read_light_level(sensor):
    """Reads the light level from the sensor."""
    try:
        light_level = sensor.lux
        return light_level
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None

def main():
    """Main function to read and print light levels."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return  # Exit if I2C initialization failed

    light_sensor = initialize_sensor(i2c_bus)
    if light_sensor is None:
        return  # Exit if sensor initialization failed

    try:
        while True:
            light_level = read_light_level(light_sensor)

            if light_level is not None:
                print(f"Ambient Light: {light_level:.2f} lux")
            else:
                print("Failed to read light level.")

            time.sleep(1)  # Wait for 1 second

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Exiting program.")

if __name__ == "__main__":
    main()

