#!/usr/bin/env python3

import atexit
import signal
import threading
import time
import sys
import traceback
from datetime import datetime

import busio
from PIL import Image, ImageDraw, ImageFont
import RPi.GPIO as GPIO
from rainbowhat import *

# Constants
MAX_BITS = 3
LED_COUNT = 14
APA102_PIN = 10
APA102_CLK_PIN = 11
BUZZER_PIN = 13
GREEN_LED_PIN = 7
BLUE_LED_PIN = 8
I2C_REINIT_DELAY = 1.0  # seconds
DISPLAY_UPDATE_INTERVAL = 0.1 # seconds

# Global Variables
bit_states = [False] * MAX_BITS
display_thread = None
display_running = False
last_display_update = 0.0

# --- GPIO Setup ---
def setup_gpio():
    """Initializes GPIO pins for the Rainbow HAT."""
    try:
        GPIO.setwarnings(False)
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(BUZZER_PIN, GPIO.OUT)
        GPIO.setup(GREEN_LED_PIN, GPIO.OUT)
        GPIO.setup(BLUE_LED_PIN, GPIO.OUT)
        GPIO.output(GREEN_LED_PIN, GPIO.HIGH)
        GPIO.output(BLUE_LED_PIN, GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup error: {e}", file=sys.stderr)
        sys.exit(1)

# --- I2C Setup ---
def setup_i2c():
    """Initializes the I2C bus and the 14-segment display."""
    try:
        i2c = busio.I2C(RainbowHat.SCL, RainbowHat.SDA)
        disp = 14segment.Segment(i2c)
        return disp, i2c
    except Exception as e:
        print(f"I2C setup error: {e}", file=sys.stderr)
        sys.exit(1)

# --- Display Functions ---
def update_display(disp, i2c):
    """Updates the 14-segment display with the current binary value."""
    global last_display_update

    current_time = time.time()
    if current_time - last_display_update < DISPLAY_UPDATE_INTERVAL:
        return

    last_display_update = current_time

    try:
        binary_string = "".join(["1" if state else "0" for state in bit_states])
        decimal_value = int(binary_string, 2)

        if decimal_value == 0:
            values = 0
        else:
            values = decimal_value

        if disp.available():
            disp.set_value(values)
        else:
            print(f"Display update failed: {traceback.format_exc()}", file=sys.stderr)

    except Exception as e:
        print(f"Display update error: {e}", file=sys.stderr)


def display_loop(disp, i2c):
    """Continuously updates the display in a separate thread."""
    global display_running
    while display_running:
        update_display(disp, i2c)
        time.sleep(0.1)


# --- APA102 LED Strip Functions ---
def setup_apa102():
    """Initializes the APA102 LED strip."""
    try:
        global apa102
        apa102 = APA102(pin=APA102_PIN, clock_pin=APA102_CLK_PIN)
        apa102.begin()
    except Exception as e:
        print(f"APA102 setup error: {e}", file=sys.stderr)
        sys.exit(1)


def update_apa102():
    """Updates the APA102 LED strip based on the binary value."""
    global last_display_update

    current_time = time.time()
    if current_time - last_display_update < DISPLAY_UPDATE_INTERVAL:
        return

    last_display_update = current_time

    try:
        binary_string = "".join(["1" if state else "0" for state in bit_states])
        decimal_value = int(binary_string, 2)

        if decimal_value == 0:
            apa102.clear()
        else:
            apa102.set_pixel(decimal_value - 1)  # Adjust to 0-based index
    except Exception as e:
        print(f"APA102 update error: {e}", file=sys.stderr)


def apa102_loop():
    """Continuously updates the APA102 LED strip in a separate thread."""
    global display_running
    while display_running:
        update_apa102()
        time.sleep(0.1)


# --- Touchpad Event Handling ---
def touch_pressed(channel):
    """Handles touchpad press events."""
    global bit_states

    try:
        if channel == touchpad_a_pin:
            bit_states[0] = not bit_states[0]
        elif channel == touchpad_b_pin:
            bit_states[1] = not bit_states[1]
        elif channel == touchpad_c_pin:
            bit_states[2] = not bit_states[2]
        else:
            print(f"Unknown touchpad channel: {channel}", file=sys.stderr)
    except Exception as e:
        print(f"Touchpad event error: {e}", file=sys.stderr)


# --- Buzzer and LED Control ---
def buzzer_on():
    """Turns the buzzer on."""
    try:
        GPIO.output(BUZZER_PIN, GPIO.HIGH)
    except Exception as e:
        print(f"Buzzer on error: {e}", file=sys.stderr)


def buzzer_off():
    """Turns the buzzer off."""
    try:
        GPIO.output(BUZZER_PIN, GPIO.LOW)
    except Exception as e:
        print(f"Buzzer off error: {e}", file=sys.stderr)


def led_green_on():
    """Turns the green LED on."""
    try:
        GPIO.output(GREEN_LED_PIN, GPIO.HIGH)
    except Exception as e:
        print(f"Green LED on error: {e}", file=sys.stderr)


def led_green_off():
    """Turns the green LED off."""
    try:
        GPIO.output(GREEN_LED_PIN, GPIO.LOW)
    except Exception as e:
        print(f"Green LED off error: {e}", file=sys.stderr)


def led_blue_on():
    """Turns the blue LED on."""
    try:
        GPIO.output(BLUE_LED_PIN, GPIO.HIGH)
    except Exception as e:
        print(f"Blue LED on error: {e}", file=sys.stderr)


def led_blue_off():
    """Turns the blue LED off."""
    try:
        GPIO.output(BLUE_LED_PIN, GPIO.LOW)
    except Exception as e:
        print(f"Blue LED off error: {e}", file=sys.stderr)


# --- Font Management ---
def get_font():
    """Returns a list of available fonts."""
    return [f.name for f in ImageFont.load_default().families()]

# --- Display Update (Functional Approach) ---
def create_image():
    """Creates a new image for displaying the binary representation."""
    return Image.new("RGB", (64, 8), "BLACK")


def draw_binary_image(image, bit_states):
    """Draws the binary representation on the image."""
    draw = ImageDraw.Draw(image)
    font = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 12)  # Use a default font
    x = 0
    y = 0

    for i, state in enumerate(bit_states):
        if state:
            color = "RED"
        else:
            color = "GREEN"

        draw.rectangle((x, y, x + 8, y + 2), fill=color)
        draw.text((x + 2, y + 4), str(2**i), font=font, fill="WHITE")

        x += 8
        if x + 8 > 64:
            x = 0
            y += 8

    return image


def display_frame(image, disp, i2c):
    """Displays the image on the 14-segment display."""
    try:
        disp.image(image)
    except Exception as e:
        print(f"Display update error: {e}", file=sys.stderr)


# --- Main Program ---
def main():
    """Main function to run the binary counter."""
    global bit_states, display_thread, display_running

    try:
        setup_gpio()
        touchpad_a_pin = RainbowHat.TOUCHPAD_A
        touchpad_b_pin = RainbowHat.TOUCHPAD_B
        touchpad_c_pin = RainbowHat.TOUCHPAD_C
        touchpad_a_channel = RainbowHat.TOUCHPAD_A_CHANNEL
        touchpad_b_channel = RainbowHat.TOUCHPAD_B_CHANNEL
        touchpad_c_channel = RainbowHat.TOUCHPAD_C_CHANNEL

        disp, i2c = setup_i2c()
        setup_apa102()

        GPIO.add_event_detect(touchpad_a_pin, GPIO.FALLING, callback=touch_pressed, bouncetime=200)
        GPIO.add_event_detect(touchpad_b_pin, GPIO.FALLING, callback=touch_pressed, bouncetime=200)
        GPIO.add_event_detect(touchpad_c_pin, GPIO.FALLING, callback=touch_pressed, bouncetime=200)

        atexit.register(lambda: cleanup_gpio())  # Ensure cleanup on exit

        display_running = True
        display_thread = threading.Thread(target=display_loop, args=(disp, i2c), daemon=True)
        display_thread.start()

        apa102_thread = threading.Thread(target=apa102_loop, daemon=True)
        apa102_thread.start()

        print("Binary counter started. Press Ctrl+C to exit.")

        while True:
            time.sleep(0.1)  # Reduce CPU usage

    except KeyboardInterrupt:
        print("\nExiting program...")
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
        traceback.print_exc()
    finally:
        global display_running
        display_running = False
        if display_thread:
            display_thread.join(timeout=1)
        if apa102_thread:
            apa102_thread.join(timeout=1)
        cleanup_gpio()


def cleanup_gpio():
    """Cleans up GPIO resources."""
    print("Cleaning up GPIO...")
    try:
        GPIO.cleanup()
        if 'disp' in locals() and 'i2c' in locals():
            disp.clear()
    except Exception as e:
        print(f"GPIO cleanup error: {e}", file=sys.stderr)


if __name__ == "__main__":
    main()

