# A simple program to read light levels and control LED brightness on Raspberry Pi

import time
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# Define the GPIO pin for the LED
LED_PIN = 18

# Define the I2C address of the light sensor
TSL2561_ADDRESS = 0x29

# Define the PWM frequency for the LED
PWM_FREQUENCY = 1000

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_light_sensor(i2c_bus):
    """Initializes the TSL2561 light sensor."""
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c_bus, address=TSL2561_ADDRESS)
        return sensor
    except Exception as e:
        print(f"Error initializing light sensor: {e}")
        return None

def initialize_gpio(led_pin):
    """Initializes the GPIO pin for the LED."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(led_pin, GPIO.OUT)
        pwm_led = GPIO.PWM(led_pin, PWM_FREQUENCY)
        pwm_led.start(0)  # Start with 0% duty cycle
        return pwm_led
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        return None

def read_light_level(sensor):
    """Reads the light level from the sensor."""
    try:
        light_level = sensor.lux
