import RPi.GPIO as GPIO
import time
import sys

# Constants
LED_PIN = 17
Blink_Frequency = 1  # Hz

def initialize_gpio():
    """Initializes the GPIO settings."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT)
        return True
    except Exception as e:
        print(f"GPIO initialization error: {e}")
        return False

def blink_led(led, frequency, on_time, off_time):
    """Blinks the LED at a specified frequency."""
    try:
        while True:
            led.on()
            time.sleep(on_time)
            led.off()
            time.sleep(off_time)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"Error during LED blinking: {e}")
    finally:
        led.close()  # Ensure LED is released


def main():
    """Main function to control the LED blinking."""
    if not initialize_gpio():
        print("GPIO initialization failed. Exiting.")
        sys.exit(1)

    try:
        led = GPIO.PWM(LED_PIN, Blink_Frequency)
        led.start(0)  # Start PWM with 0% duty cycle (LED off)
        blink_led(led, Blink_Frequency, 1, 1) # Blinking with 1 second on and off

    except RuntimeError as e:
        print(f"RuntimeError: {e}.  Are you running as root?")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if 'led' in locals():  # Check if 'led' exists before calling close()
            led.stop()
        GPIO.cleanup()
        print("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

