import RPi.GPIO as GPIO
import time
from functools import partial

# Constants for GPIO pins and PWM frequency
GPIO_RED = 17
GPIO_GREEN = 27
GPIO_BLUE = 22
PWM_FREQUENCY = 100

def setup_gpio(red_pin, green_pin, blue_pin):
    """Initializes GPIO pins and returns a dictionary of PWM objects."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(red_pin, GPIO.OUT)
        GPIO.setup(green_pin, GPIO.OUT)
        GPIO.setup(blue_pin, GPIO.OUT)
        return {
            "red": GPIO.PWM(red_pin, PWM_FREQUENCY),
            "green": GPIO.PWM(green_pin, PWM_FREQUENCY),
            "blue": GPIO.PWM(blue_pin, PWM_FREQUENCY)
        }
    except Exception as e:
        raise RuntimeError(f"GPIO setup failed: {e}")

def start_pwm(pwm_objects):
    """Starts PWM with initial duty cycles."""
    try:
        for pin, pwm in pwm_objects.items():
            pwm.start(100)  # Full brightness
        return pwm_objects
    except Exception as e:
        raise RuntimeError(f"PWM start failed: {e}")

def set_color(pwm_objects, red_duty_cycle=100, green_duty_cycle=50, blue_duty_cycle=25):
    """Sets the RGB LED color."""
    try:
        for pin, pwm in pwm_objects.items():
            if pin == "red":
                pwm.ChangeDutyCycle(red_duty_cycle)
            elif pin == "green":
                pwm.ChangeDutyCycle(green_duty_cycle)
            elif pin == "blue":
                pwm.ChangeDutyCycle(blue_duty_cycle)
    except Exception as e:
        raise RuntimeError(f"Color setting failed: {e}")

def run_color(pwm_objects, duration=2):
    """Runs the color sequence."""
    try:
        print('Running LED with color (Red=100, Green=50, Blue=25)')
        set_color(pwm_objects)
        time.sleep(duration)
        print('LED with color stopped')
    except KeyboardInterrupt:
        print('Script interrupted. Stopping LED...')
    except Exception as e:
        raise RuntimeError(f"Runtime error: {e}")
    finally:
        stop_pwm(pwm_objects)

def stop_pwm(pwm_objects):
    """Stops PWM and cleans up GPIO."""
    try:
        for pin, pwm in pwm_objects.items():
            pwm.stop()
        GPIO.cleanup()
        print('GPIO cleanup done')
    except Exception as e:
        raise RuntimeError(f"GPIO cleanup failed: {e}")

def main():
    """Main function to orchestrate the RGB LED program."""
    try:
        pwm_dict = setup_gpio(GPIO_RED, GPIO_GREEN, GPIO_BLUE)
        pwm_objects = start_pwm(pwm_dict)
        run_color(pwm_objects)
    except RuntimeError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

