import smbus
import time

# I2C address of the MPU6050
MPU_ADDRESS = 0x68

# Initialize I2C bus
i2c_bus = smbus.SMBus(1)

def get_sensor_data():
    """Reads raw accelerometer data from the MPU6050."""
    try:
        raw_data = i2c_bus.read_i2c_block_data(MPU_ADDRESS, 0x3B, 6)
        x = (raw_data[0] << 8) | raw_data[1]
        y = (raw_data[4] << 8) | raw_data[5]
        return x, y
    except Exception as error:
        print("Sensor read error:", error)
        return None, None

def analyze_tilt(x_value, y_value):
    """Analyzes accelerometer data to determine tilt direction."""
    if x_value < -0.1 and y_value > 0.1:
        return "tilting left"
    elif x_value > 0.1 and y_value < -0.1:
        return "tilting right"
    elif y_value < -0.1:
        return "tilting forward"
    elif y_value > 0.1:
        return "tilting back"
    else:
        return "level"

def main():
    """Main function to read and analyze accelerometer data."""
    try:
        for _ in range(5):
            x, y = get_sensor_data()
            if x is not None and y is not None:
                tilt_direction = analyze_tilt(x, y)
                print("Tilt:", tilt_direction)
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    finally:
        i2c_bus.close()
        print("I2C bus closed.")

if __name__ == "__main__":
    main()

