import RPi.GPIO as GPIO
import time
import datetime

# Define the GPIO pin connected to the relay
RELAY_PIN = 17

# Define the sunrise and sunset times (24-hour format)
sunrise_time = "07:00:00"
sunset_time = "19:00:00"

def initialize_gpio(pin):
    """Initializes the GPIO pin as an output."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT)
        GPIO.output(pin, GPIO.HIGH)  # Initialize relay to OFF (door closed)
        print(f"GPIO pin {pin} initialized.")
    except RuntimeError:
        print("Error: Could not initialize GPIO.  Are you running with sudo?")
        exit()

def get_current_time():
    """Returns the current time in HH:MM:SS format."""
    return datetime.datetime.now().time()

def is_between_time(current_time, sunrise, sunset):
    """Checks if the current time is between the sunrise and sunset times."""
    return sunrise <= current_time <= sunset

def control_door(pin, open_door):
    """Controls the door relay (open or close)."""
    if open_door:
        GPIO.output(pin, GPIO.LOW)  # Activate relay to open the door
        print("Opening the chicken coop door.")
    else:
        GPIO.output(pin, GPIO.HIGH)  # Deactivate relay to close the door
        print("Closing the chicken coop door.")

def main():
    """Main function to control the chicken coop door."""
    initialize_gpio(RELAY_PIN)

    try:
        while True:
            current_time = get_current_time()
            print(f"Current time: {current_time.strftime('%H:%M:%S')}")

            if is_between_time(current_time, sunrise, sunset):
                control_door(RELAY_PIN, True)  # Open the door
            else:
                control_door(RELAY_PIN, False) # Close the door

            time.sleep(60)  # Wait 60 seconds

    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

