#!/usr/bin/env python3
# Interactive Art Installation Motor Controller
# Author: Bard
# Date: October 26, 2023
# Controls a DC motor with an L298N driver.

import RPi.GPIO as GPIO
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Motor driver pins (BCM numbering)
MOTOR_ENABLE_PIN = 12  # PWM0: 12, PWM1: 13, PWM2: 19
MOTOR_FORWARD_PIN = 20
MOTOR_REVERSE_PIN = 21

# Motor parameters
MAX_SPEED = 80  # Maximum duty cycle percentage
SPEED_RAMP_STEP = 5 # Number of steps in the speed ramp
SPEED_DELAY = 0.3 # Delay between speed steps in seconds

# Global variable for current direction
current_direction = "forward"
motor_pwm = None

def setup():
    """Initializes GPIO and PWM."""
    global motor_pwm
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(MOTOR_ENABLE_PIN, GPIO.OUT)
        GPIO.setup(MOTOR_FORWARD_PIN, GPIO.OUT)
        GPIO.setup(MOTOR_REVERSE_PIN, GPIO.OUT)
        motor_pwm = GPIO.PWM(MOTOR_ENABLE_PIN, 1000) # 1kHz PWM frequency
        motor_pwm.start(0) # Start with 0% duty cycle
        logging.info("GPIO and PWM setup successful.")
    except Exception as e:
        logging.error(f"Setup failed: {e}")
        cleanup() # Clean up GPIO in case of error
        raise  # Re-raise the exception to halt execution


def set_direction(forward=True, reverse=False):
    """Sets the motor direction."""
    global current_direction
    try:
        GPIO.output(MOTOR_FORWARD_PIN, forward)
        GPIO.output(MOTOR_REVERSE_PIN, reverse)
        current_direction = "forward" if forward else "reverse"
        logging.info(f"Direction set to: {'forward' if forward else 'reverse'}")
    except Exception as e:
        logging.error(f"Direction setting failed: {e}")


def ramp_speed(speed):
    """Ramps the motor speed from 0% to the target speed."""
    try:
        if speed <= 0 or speed >= MAX_SPEED:
            raise ValueError("Speed must be between 0 and MAX_SPEED")

        for duty_cycle in range(0, speed + 1, SPEED_RAMP_STEP):
            motor_pwm.ChangeDutyCycle(duty_cycle)
            time.sleep(SPEED_DELAY)
        logging.info(f"Speed ramped to {speed}%")

    except ValueError as ve:
        logging.error(f"Invalid speed value: {ve}")
    except Exception as e:
        logging.error(f"Speed ramp failed: {e}")


def stop():
    """Stops the motor."""
    try:
        motor_pwm.ChangeDutyCycle(0)
        logging.info("Motor stopped.")
    except Exception as e:
        logging.error(f"Stop failed: {e}")


def cleanup():
    """Cleans up GPIO."""
    try:
        if motor_pwm:
            motor_pwm.stop()
        GPIO.cleanup()
        logging.info("GPIO cleanup successful.")
    except Exception as e:
        logging.error(f"Cleanup failed: {e}")


def main():
    """Main control loop."""
    try:
        setup()
        set_direction(forward=True)  # Initially moving forward

        while True:
            key = input("Enter 's' to increase speed, 'd' to decrease, 'x' to stop, 'q' to quit: ").lower()

            if key == 's':
                ramp_speed(min(MAX_SPEED, speed + SPEED_RAMP_STEP))  # Limit max speed
            elif key == 'd':
                ramp_speed(max(0, speed - SPEED_RAMP_STEP))  # Limit min speed
            elif key == 'x':
                stop()
            elif key == 'q':
                break
            else:
                logging.warning("Invalid input.")

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

