#!/usr/bin/python3

"""Provides a functional approach for controlling a DC motor via an L298N driver on a Raspberry Pi."""

import time
import logging
from functools import partial
from typing import Callable, Optional

try:
    from gpiozero import PWMOutputDevice, GPIOZero
except ImportError:
    GPIOZero = None
    PWMOutputDevice = None

from typing import Callable, Optional

# Configure logging
logger = logging.getLogger(__name__)
logger.setLevel(logging.INFO)

# Constants
MAX_DUTY_CYCLE = 255
DEFAULT_FREQUENCY = 1000  # Hz


class MotorError(Exception):
    """Custom exception for motor-related errors."""
    pass


def validate_pin(pin: int) -> None:
    """Validates that the provided pin number is positive."""
    if pin <= 0:
        raise ValueError("Pin number must be a positive integer.")


def create_motor(driver: GPIOZero.PWMOutputDevice, pin: int, frequency: int = DEFAULT_FREQUENCY) -> "Motor":
    """Creates and configures a Motor instance."""

    validate_pin(pin)

    try:
        motor = driver.pwm[pin - 1]  # Adjust index for BCM numbering
        motor.frequency = frequency
        motor.max_duty_cycle = MAX_DUTY_CYCLE
        return Motor(motor, pin)  # Return Motor instance
    except Exception as e:
        logger.error(f"Error creating motor instance: {e}")
        raise MotorError(f"Error creating motor instance: {e}")


class Motor:
    """Represents a DC motor controlled by an L298N driver."""

    def __init__(self, motor_component: PWMOutputDevice, pin: int, frequency: int = DEFAULT_FREQUENCY):
        """Initializes the motor."""
        if not isinstance(motor_component, PWMOutputDevice):
            raise MotorError("motor_component must be a PWMOutputDevice instance.")
        self.motor = motor_component
        self.pin = pin
        self.frequency = frequency
        self.duty_cycle = 0
        self._set_duty_cycle = partial(self.motor.pwm, pin - 1, frequency=frequency)  # Pre-configure with frequency

    def close(self) -> None:
        """Stops the motor and releases resources."""
        try:
            self._set_duty_cycle(0)
            logger.info(f"Motor on pin {self.pin} closed.")
        except Exception as e:
            logger.error(f"Error closing motor: {e}")

    def stop(self) -> None:
        """Stops the motor."""
        self._set_duty_cycle(0)

    def set_frequency(self, frequency: int) -> int:
        """Sets the motor frequency."""
        validate_pin(self.pin)
        try:
            self._set_duty_cycle.frequency = frequency  # Pre-configure with duty cycle
            self.frequency = self._set_duty_cycle.frequency
            logger.info(f"Motor on pin {self.pin} frequency set to {self.frequency} Hz.")
            return self.frequency
        except Exception as e:
            logger.error(f"Error setting frequency for motor on pin {self.pin}: {e}")
            return self.frequency  # Return last known value


    def set_duty_cycle(self, duty_cycle: int) -> int:
        """Sets the motor duty cycle."""
        validate_pin(self.pin)
        if not 0 <= duty_cycle <= MAX_DUTY_CYCLE:
            raise ValueError(f"Duty cycle must be between 0 and {MAX_DUTY_CYCLE}.")
        try:
            self._set_duty_cycle(duty_cycle)
            self.duty_cycle = self._set_duty_cycle.duty_cycle
            logger.info(f"Motor on pin {self.pin} duty cycle set to {self.duty_cycle}.")
            return self.duty_cycle
        except Exception as e:
            logger.error(f"Error setting duty cycle for motor on pin {self.pin}: {e}")
            return self.duty_cycle  # Return last known value


    def get_duty_cycle(self) -> int:
        """Gets the motor duty cycle."""
        return self.duty_cycle

    def __repr__(self) -> str:
        """Returns a string representation of the motor state."""
        return f"Motor(pin={self.pin}, frequency={self.frequency}, duty_cycle={self.duty_cycle})"


def create_motor_driver(lib: Type(GPIOZero), pin: int, frequency: int = DEFAULT_FREQUENCY) -> "Motor":
    """Creates a Motor instance based on the provided library."""
    if lib is None:
        raise ValueError("GPIOZero library must be installed.")

    try:
        driver = lib.PWM(pin)
        driver.start(0)  # Initialize PWM with 0 duty cycle
        return create_motor(driver, pin, frequency)
    except Exception as e:
        logger.error(f"Error creating motor driver instance: {e}")
        raise MotorError(f"Error creating motor driver instance: {e}")

