import time
import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO

# Define constants
PUMP_GPIO_PIN = 17
SOIL_MOISTURE_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10

# Initialize I2C bus
def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

# Initialize the soil moisture sensor
def initialize_sensor(i2c_bus):
    """Initializes the soil moisture sensor."""
    try:
        return adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=0x4E)
    except Exception as e:
        print(f"Error initializing sensor: {e}")
        return None

# Initialize the GPIO pin for the water pump
def initialize_gpio(pin):
    """Initializes the GPIO pin for the water pump."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)
    GPIO.output(pin, GPIO.LOW)  # Ensure pump is initially off

# Read soil moisture level
def read_soil_moisture(sensor):
    """Reads the soil moisture level from the sensor."""
    try:
        return sensor.moisture_read()
    except Exception as e:
        print(f"Error reading soil moisture: {e}")
        return None

# Control the water pump
def control_water_pump(pin, moisture_level, threshold):
    """Controls the water pump based on the soil moisture level."""
    try:
        if moisture_level is not None:
            if moisture_level < threshold:
                GPIO.output(pin, GPIO.HIGH)  # Turn on pump
                print("Water Pump ON: Soil too dry")
            else:
                GPIO.output(pin, GPIO.LOW)  # Turn off pump
                print("Water Pump OFF: Soil moisture sufficient")
    except Exception as e:
        print(f"Error controlling pump: {e}")

# Main function
def main():
    """Main function to monitor soil moisture and control the water pump."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    soil_sensor = initialize_sensor(i2c_bus)
    if soil_sensor is None:
        return

    initialize_gpio(PUMP_GPIO_PIN)

    try:
        while True:
            moisture = read_soil_moisture(soil_sensor)
            if moisture is not None:
                print(f"Soil Moisture: {moisture}")
                control_water_pump(PUMP_GPIO_PIN, moisture, SOIL_MOISTURE_THRESHOLD)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure pump is off and GPIO is cleaned up on exit
        GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)
        GPIO.cleanup()
        if i2c_bus:
            i2c_bus.deinit()

if __name__ == "__main__":
    main()

