import time
import serial
import logging
import signal
import os
from functools import partial

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
SERIAL_PORT = "/dev/serial0"  # Raspberry Pi's UART port
BAUDRATE = 115200
TIMEOUT = 1
MODBUS_SLAVE_ADDRESS = 1  # Replace with your Modbus slave address
class ModbusRTUException(Exception):
    """Custom exception for Modbus RTU communication errors."""
    pass


def create_serial_connection(port, baudrate, timeout):
    """Establishes a serial connection."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        raise ModbusRTUException(f"Error opening serial port {port}: {e}")


def check_serial_connection(connection):
    """Checks if the serial connection is active."""
    if connection and connection.is_open:
        return True
    return False


def close_serial_connection(connection):
    """Closes the serial connection."""
    if connection and connection.is_open:
        connection.close()


def write_modbus_command(connection, slave_address, function_code, data):
    """Sends a Modbus RTU command to the servo motor."""
    try:
        # Modbus RTU protocol requires a start byte (0x01), function code, and data
        command = bytes([0x01]) + \
                  bytes([slave_address]) + \
                  bytes([function_code]) + \
                  data
        connection.write_all(command)
        return True
    except serial.SerialException as e:
        raise ModbusRTUException(f"Error writing to serial port: {e}")


def read_modbus_response(connection, slave_address, function_code, count=1):
    """Reads a Modbus RTU response from the servo motor."""
    try:
        # Modbus RTU protocol requires a start byte (0x01), function code, and data
        command = bytes([0x01]) + \
                  bytes([slave_address]) + \
                  bytes([function_code]) + \
                  bytes([count])
        response = connection.read_all(command)
        return response
    except serial.SerialException as e:
        raise ModbusRTUException(f"Error reading from serial port: {e}")


def validate_data(data):
    """Validates if the received data is not empty."""
    return bool(data)


def get_servo_position(response):
