import serial
import RPi.GPIO as GPIO
import time
import logging
import signal
import os
import functools

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
GSM_PORT = "/dev/serial0"
BAUDRATE = 115200
TIMEOUT = 2
POWER_ENABLE_PIN = 4  # BCM pin 4
GPS_READ_TIMEOUT = 5  # seconds
MAX_READ_ATTEMPTS = 5  # Maximum attempts to read from the serial port


# Initialize GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(POWER_ENABLE_PIN, GPIO.OUT)

# Global variable for serial port
gsm_serial = None

# --- Functional Approach ---

def open_serial_port(port, baudrate, timeout):
    """Opens and returns a serial port. Handles potential errors."""
    try:
        gsm_serial = serial.Serial(port, baudrate=baudrate, timeout=timeout)
        logging.info(f"Serial port {port} opened successfully.")
        return gsm_serial
    except serial.SerialException as e:
        logging.error(f"Error opening serial port {port}: {e}")
        return None


def close_serial_port(serial_port):
    """Closes a serial port if it's open."""
    if serial_port and serial_port.is_open:
        serial_port.close()
        logging.info("Serial port closed.")


def write_at_command(serial_port, command, expected_reply="OK"):
    """Writes an AT command to the GSM module and checks for a reply."""
    try:
        serial_port.write((command + '\r\n').encode())
        logging.debug(f"Sent command: {command}")
        for _ in range(MAX_READ_ATTEMPTS):
            response = serial_port.readline().decode('utf-8', errors='ignore')
            if response == expected_reply:
                logging.debug(f"Received reply: {response}")
                return True
            time.sleep(0.1)
        logging.warning(f"Command '{command}' timed out or no reply received.")
        return False
    except serial.SerialException as e:
        logging.error(f"Error writing to serial port: {e}")
        return False


def read_response(serial_port, max_attempts=MAX_READ_ATTEMPTS):
    """Reads data from the serial port, handling potential errors."""
    for _ in range(max_attempts):
        try:
            response = serial_port.readline().decode('utf-8', errors='ignore')
            if response:
                return response
        except serial.SerialException as e:
            logging.error(f"Error reading from serial port: {e}")
            return None
        time.sleep(0.1)
    logging.warning("Timeout waiting for response from serial port.")
    return None


def send_data_over_tcp(serial_port, ip, port, data):
    """Sends data over TCP."""
    try:
        at_command = f'AT+CIPSTART="TCP","{ip}",{port}\r\n'
        if write_at_command(serial_port, at_command):
            at_command = f'AT+CIPSEND\r\n'
            if write_at_command(serial_port, at_command, expected_reply="OK"):
                serial_port.write((data + '\r\n').encode())
                time.sleep(1)
                at_command = f'AT+CIPCLOSE\r\n'
                if write_at_command(serial_port, at_command):
                    logging.info(f"Data sent successfully. Response: {read_response(serial_port)}")
                    return True
            else:
                logging.error("Failed to send data.")
                return False
        else:
            logging.error("Failed to start TCP connection.")
            return False
    except serial.SerialException as e:
        logging.error(f"Error sending data over TCP: {e}")
        return False


def set_gpio_power(power_enable_pin, enable=True):
    """Turns the GSM module power on or off."""
    try:
        GPIO.output(power_enable_pin, GPIO.HIGH if enable else GPIO.LOW)
        logging.debug(f"Power set to: {'ON' if enable else 'OFF'}")
    except Exception as e:
        logging.error(f"Error setting GPIO power: {e}")


def set_gps_reporting_interval(interval_seconds=10):
    """Sets the GPS reporting interval."""
    try:
        at_command = f'AT+GPSRD={interval_seconds}\r\n'
        if write_at_command(gsm_serial, at_command):
            logging.info(f"GPS reporting interval set to {interval_seconds} seconds.")
            return True
        else:
            logging.error("Failed to set GPS reporting interval.")
            return False
    except Exception as e:
        logging.error(f"Error setting GPS reporting interval: {e}")
        return False


def set_message_storage(storage='SM'):
    """Sets the message storage location."""
    try:
        at_command = f'AT+CPMS="{storage}","{storage}","{storage}"\r\n'
        if write_at_command(gsm_serial, at_command):
            logging.info(f"Message storage set to '{storage}'.")
            return True
        else:
            logging.error("Failed to set message storage.")
            return False
    except Exception as e:
        logging.error(f"Error setting message storage: {e}")
        return False


def send_message(storage, number, message):
    """Sends a message to the specified storage and number."""
    try:
        at_command = f'AT+CMGF=1\r\n'  # Set to text mode
        if write_at_command(gsm_serial, at_command):
            at_command = f'AT+CMGS="{number}"\r\n'
            if write_at_command(gsm_serial, message, expected_reply='>'):
                at_command = f'AT+CMGD={storage},1\r\n'  # Delete older messages
                if write_at_command(gsm_serial, at_command):
                    logging.info(f"Message sent to '{storage}' under '{number}'.")
                    return True
                else:
                    logging.error("Failed to send message.")
                    return False
            else:
                logging.error("Failed to send message (recipient).")
                return False
    except Exception as e:
        logging.error(f"Error sending message: {e}")
        return False


def send_tcp_data(data, ip='192.168.100.12', port=50):
    """Sends data over TCP as AT commands."""
    return send_data_over_tcp(gsm_serial, ip, port, data)


def verify_module_connectivity():
    """Verifies module connectivity by reading the "OK" reply."""
    return write_at_command(gsm_serial, 'AT\r\n', expected_reply='OK')


def check_gps_validity():
    """Checks GPS validity by reading the 'GPS' identifier."""
    return write_at_command(gsm_serial, 'AT+GPSRD=1\r\n' if gsm_serial else False)  # Still checks even if not attached


def read_gps_data():
    """Reads and decodes GPS data from the serial port."""
    if not gsm_serial:
        logging.error("Serial port not open. Cannot read GPS data.")
        return None
    try:
        at_command = 'AT+GPSRD=1\r\n'
        if write_at_command(gsm_serial, at_command):
            time.sleep(1)  # Wait for data
            response = read_response(gsm_serial)
            if response:
                # Placeholder for actual GPS data parsing.  Requires complex parsing of multiple NMEA sentences.
                # This is a simplified example.  A real implementation would need to decode and parse NMEA sentences.
                logging.debug(f"GPS Data: {response}")
                return response
            else:
                logging.warning("No GPS data received.")
                return None
        else:
            logging.error("Failed to read GPS data.")
            return None
    except Exception as e:
        logging.error(f"Error reading GPS data: {e}")
        return None


def get_serial_port():
    """Returns the serial port, creating it if it doesn't exist."""
    if not os.path.exists(GSM_PORT):
        try:
            open_serial_port(GSM_PORT, BAUDRATE, TIMEOUT)
        except Exception as e:
            logging.error(f"Failed to open serial port {GSM_PORT}: {e}")
            raise  # Re-raise the exception to signal failure
    return open_serial_port(GSM_PORT, BAUDRATE, TIMEOUT)


def close():
    """Closes the serial port and cleans up GPIO."""
    if gsm_serial:
        close_serial_port(gsm_serial)
    GPIO.cleanup()


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    logging.info("Received signal, shutting down...")
    close()
    exit(0)


# Create a context manager for serial port management
class GSMModule:
    def __enter__(self):
        """Context manager entry point, opens the serial port."""
        global gsm_serial
        gsm_serial = get_serial_port()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit point, closes the serial port."""
        close()

    def send(self, command, expected_reply="OK", max_attempts=MAX_READ_ATTEMPTS):
        """Generic send command function."""
        write_at_command(self.gsm_serial, command, expected_reply)

    def read(self, max_attempts=MAX_READ_ATTEMPTS):
        """Generic read function."""
        return read_response(self.gsm_serial, max_attempts)

    def write(self, data):
        """Generic write function."""
        return send_data_over_tcp(self.gsm_serial, '192.168.100.12', 50, data)


    def set_power(self, enable=True):
        """Generic set power function."""
        set_gpio_power(POWER_ENABLE_PIN, enable)


    def set_gps_reporting(self, interval_seconds=10):
        """Generic set GPS reporting interval."""
        return set_gps_reporting_interval(interval_seconds)


    def set_message_storage(self, storage='SM'):
        """Generic set message storage location."""
        return set_message_storage(storage)


    def send_message(self, storage, number, message):
        """Generic send message function."""
        return send_message(self.set_message_storage(storage), number, message)


    def verify_connectivity(self):
        """Generic verify connectivity function."""
        return verify_module_connectivity()

    def check_gps(self):
        """Generic check GPS function."""
        return check_gps_validity()

    def read_gps(self):
        """Generic read GPS data function."""
        return read_gps_data()


if __name__ == '__main__':
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Example Usage (Using a functional approach with the defined functions)
    with GSMModule() as gsm:
        if gsm.verify_connectivity():
            gsm.set_power(enable=False)
            gsm.set_gps_reporting(interval_seconds=5)
            message = "Test Message"
            if gsm.send_message("SM", "0123456789", message):
                print(f"Message sent successfully: {message}")
            else:
                print("Failed to send message.")
        else:
            print("Failed to connect to GSM module.")

