import time
import logging
import threading
from typing import Callable, Optional

import Adafruit_PCA9685
import board
import busio

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_ANGLE = 90
SERVO_CHANNELS = 16  # Number of servo channels being controlled
MIN_ANGLE = 0
MAX_ANGLE = 180

# Initialize I2C bus and PCA9685 servo controller
try:
    i2c = busio.I2C(board.SCL, board.SDA)
    pca = Adafruit_PCA9685.PCA9685(i2c)
except Exception as e:
    logging.error(f"Error initializing I2C or PCA9685: {e}")
    pca = None  # Set pca to None to indicate initialization failure

# Global lock for controlling access to servo channels
servo_lock = threading.Lock()


def _safe_servo_move(channel: int, angle: int, set_angle: Callable[[int, int], None], error_handler: Callable[[], None]) -> None:
    """Safely moves a servo to an angle, handling potential errors."""
    with servo_lock:
        if pca is not None:
            try:
                set_angle(channel, angle)
            except Exception as e:
                error_handler()
                logging.error(f"Error setting servo {channel} to {angle} degree: {e}")


def move_servo(channel: int, target_angle: int, step_size: int = 1, delay: float = 0.04) -> None:
    """Moves a servo smoothly to a target angle."""
    if pca is None:
        logging.warning("PCA9685 not initialized. Skipping servo movement.")
        return

    if not MIN_ANGLE <= target_angle <= MAX_ANGLE:
        logging.error(f"Target angle {target_angle} is out of range ({MIN_ANGLE}-{MAX_ANGLE}).")
        return

    current_angle = DEFAULT_ANGLE if channel == 0 else DEFAULT_ANGLE  # Base angle by default

    if target_angle > current_angle:
        angle_range = range(int(current_angle), int(target_angle) + 1, step_size)
    else:
        angle_range = range(int(current_angle), int(target_angle) - 1, -step_size)

    for angle in angle_range:
        _safe_servo_move(channel, angle, pca.set_angle, lambda: logging.warning("Servo movement stalled")) # Call error handler for stall detection
        time.sleep(delay)


def set_servo_angle(channel: int, angle: int) -> None:
    """Generic function to set servo angle with error handling."""
    move_servo(channel, angle)


# Functional approach: create higher-order functions for specific servo actions
def create_servo_action(channel: int, angle_range: range) -> Callable[[int], None]:
    """Creates a function to move a servo within a specific angle range."""
    def servo_action(target_angle: int) -> None:
        move_servo(channel, target_angle, step_size=1, delay=0.04)  # Smaller step for finer control
    return servo_action


seek_angle = create_servo_action(2, range(30, 150)) # Example: 30-150 degrees
drop_angle = create_servo_action(1, range(160, 190)) # Example: 160-190 degrees


def drop_object_steps(seek_angle: int) -> None:
    """Performs drop object sequence."""
    seek(seek_angle)
    drop_angle(seek_angle + 30)  # Example: Lower and then raise slightly
    set_servo_angle(0, 100) # Example: Open gripper
    seek(90) # Example: Return to horizontal position


def drop_object(drop_angle: int) -> None:
    """Generic drop object function."""
    drop_object_steps(seek_angle)
    drop_angle(drop_angle + 30) # Example: Lower further
    set_servo_angle(0, 100) # Example: Keep gripper open
    set_servo_angle(0, 100) # Example: Return gripper to default


def get_pos_x(x_center: int) -> int:
    """Gets horizontal position from x_center."""
    if x_center < 160:
        return 90
    elif x_center < 320:
        return 67
    elif x_center < 480:
        return 45
    elif x_center < 640:
        return 22
    else:
        return MIN_ANGLE  # Always return a valid angle within the range



def get_pos_y(y_center: int) -> int:
    """Gets vertical position from y_center."""
    if y_center < 120:
        return 22
    elif y_center < 240:
        return 45
    elif y_center < 360:
        return 67
    elif y_center < 480:
        return 90
    else:
        return MAX_ANGLE # Always return a valid angle within the range



def collect_object_steps(seek_angle: int, drop_angle: int) -> None:
    """Collects an object."""
    pos_x = get_pos_x(240) # Example: Seek from center
    pos_y = get_pos_y(240) # Example: YSeek from center

    go_to_pos(seek_angle, pos_x, 10, 0.02) # Example: Move horizontally
    go_to_pos(pos_y, seek_angle, 10, 0.02) # Example: Move vertically
    drop_object_steps(seek_angle)
    drop_object(drop_angle)



def collect_object(drop_angle: int, x_center: int, y_center: int) -> int:
    """Generic object collection function."""
    collect_object_steps(seek_angle, drop_angle)
    return get_pos_x(x_center)



def collect_all_objects(x_center: int, y_center: int, drop_angle: int, num_cycles: int = 3) -> int:
    """Collects multiple objects."""
    pos_x = get_pos_x(y_center) # Example: Use YCenter for horizontal position

    for _ in range(num_cycles):
        pos_y = get_pos_y(y_center) # Example: Use YCenter for vertical position

        go_to_pos(x_center, pos_x, 5, 0.015) # Example: Move horizontally
        go_to_pos(pos_y, x_center, 5, 0.015) # Example: Move vertically
        drop_object_steps(x_center)
        drop_object(drop_angle)
        pos_x += 10 # Example: Increment horizontal position for next cycle
        pos_y += 10 # Example: Increment vertical position for next cycle

    return pos_x # Return final horizontal position



def collect_and_sort_objects() -> None:
    """Collects and sorts objects."""
    sorted_x_center = collect_all_objects(x_center=240, y_center=240, drop_angle=190)
    logging.info(f"Sorted objects to: {sorted_x_center}")


def collect_object_with_timeout(x_center: int, y_center: int, drop_angle: int, timeout: float) -> Optional[int]:
    """Collects an object with a timeout."""
    start_time = time.time()

    def check_timeout() -> None:
        if time.time() - start_time > timeout:
            logging.warning("Timeout reached during object collection.")

    timeout_thread = threading.Thread(target=check_timeout, daemon=True)
    timeout_thread.start()

    try:
        collected_x_center = collect_object(x_center, y_center, drop_angle)
        timeout_thread.join()  # Wait for timeout thread to finish
        return collected_x_center
    except Exception as e:
        logging.error(f"Error collecting object: {e}")
        return None


def collect_objects_recur(x_center: int, y_center: int, drop_angle: int, num_objects: int, remaining: list, result: list) -> None:
    """Collects objects recursively."""
    if len(remaining) == num_objects:
        result.append(collect_object(x_center, y_center, drop_angle))
        return

    collect_object_with_timeout(x_center, y_center, drop_angle, 10)  # Example timeout
    collect_objects_recur(x_center, y_center, drop_angle, num_objects, remaining[1:], result)


def collect_objects(num_objects: int = 5) -> list[int]:
    """Generic recursive object collection function."""
    return collect_objects_recur(x_center=num_objects, y_center=num_objects, drop_angle=190, num_objects=num_objects, remaining=[num_objects], result=[])



def go_to_pos(x_center: int, pos_x: int, step_size: int = 5, delay: float = 0.02) -> None:
    """Moves to a specific x-position."""
    if x_center < pos_x:
        angle_range = range(int(pos_x), int(x_center) + 1, step_size)
    else:
        angle_range = range(int(pos_x), int(x_center), -step_size)

    for angle in angle_range:
        _safe_servo_move(0, angle, pca.set_angle, lambda: logging.warning("Servo movement stalled")) # Call error handler for stall detection
        time.sleep(delay)


def release_all_servos() -> None:
    """Releases all servo channels."""
    with servo_lock:
        if pca is not None:
            pca.set_all_addressable_channels(0)


def main() -> None:
    """Main program loop."""
    if pca is None:
        logging.error("PCA9685 not initialized. Exiting.")
        return

    try:
        while True:
            command = input("Enter command (collect, sort, exit): ").lower()

            if command == "collect":
                collected_x_center = collect_objects()
                if collected_x_center is not None:
                    print(f"Collected object to: {collected_x_center}")
            elif command == "sort":
                collect_and_sort_objects()
            elif command == "exit":
                break
            else:
                print("Invalid command.")

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        release_all_servo_channels()


def release_all_servo_channels() -> None:
    """Safely releases all servo channels."""
    with servo_lock:
        if pca is not None:
            pca.min_usleep = 1000000
            pca.max_usleep = 1000000
            pca.set_all_addressable_channels(0)



if __name__ == "__main__":
    main()

