import RPi.GPIO as GPIO
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pins using BCM numbering
PUMP_PIN = 20
LIGHT_PIN = 21

# Initialize GPIO settings
def initialize_gpio():
    """Sets up GPIO pins for output."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(PUMP_PIN, GPIO.OUT)
    GPIO.setup(LIGHT_PIN, GPIO.OUT)
    GPIO.output(PUMP_PIN, GPIO.LOW)  # Ensure pump is initially off
    GPIO.output(LIGHT_PIN, GPIO.LOW) # Ensure light is initially off
    logging.info("GPIO setup complete.")

# Function to control the nutrient pump
def control_pump(action):
    """Controls the nutrient pump based on the given action."""
    try:
        if action == "on":
            GPIO.output(PUMP_PIN, GPIO.HIGH)
            logging.info("Nutrient pump turned ON.")
        elif action == "off":
            GPIO.output(PUMP_PIN, GPIO.LOW)
            logging.info("Nutrient pump turned OFF.")
        else:
            logging.warning(f"Invalid pump action: {action}")
    except Exception as e:
        logging.error(f"Error controlling pump: {e}")

# Function to control the grow light
def control_light(action):
    """Controls the grow light based on the given action."""
    try:
        if action == "on":
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
            logging.info("Grow light turned ON.")
        elif action == "off":
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            logging.info("Grow light turned OFF.")
        else:
            logging.warning(f"Invalid light action: {action}")
    except Exception as e:
        logging.error(f"Error controlling light: {e}")

# Function to parse the command and execute the corresponding action
def process_command(command):
    """Parses the command and executes the corresponding action."""
    try:
        command = command.lower()  # Convert to lowercase for case-insensitive matching
        if "turn the pump on" in command:
            control_pump("on")
        elif "turn the pump off" in command:
            control_pump("off")
        elif "switch the light on" in command:
            control_light("on")
        elif "switch the light off" in command:
            control_light("off")
        elif "toggle the light" in command:
            if GPIO.input(LIGHT_PIN) == GPIO.HIGH:
                control_light("off")
            else:
                control_light("on")
        else:
            logging.warning(f"Unknown command: {command}")
    except Exception as e:
        logging.error(f"Error processing command: {e}")

# Main function to run the voice-controlled hydroponics system
def main():
    """Main function to run the voice-controlled hydroponics system."""
    try:
        initialize_gpio()
        logging.info("Hydroponics system started. Ready to receive commands.")
        while True:
            command = input("Enter command (e.g., 'turn the pump on'): ")
            process_command(command)
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Ensure all actuators are turned off on exit
        control_pump("off")
        control_light("off")
        GPIO.cleanup()
        logging.info("GPIO cleanup complete. System shutdown.")

# Run the main function
if __name__ == "__main__":
    main()

