        self.ld = ld
        self.hd = hd
        self.pos_h = 0
        self.pos_v = 0
        self.str = ""
        self.path = []
        self._map = {
            "1": self.move_to_hz, "2": self.move_to_vz, "3": self.move_to_hr, "4": self.move_to_vr,
            "5": self.move_to_hl, "6": self.move_to_vl, "7": self.move_to_dr, "8": self.move_to_dl,
            "9": self.move_to_cr, "e": self.turn_on_laser, "o": self.turn_off_laser,
