        try:
            self.servo_h.position = pos
            self.pos_h = pos
            return self._get_pos("h", pos)
        except Exception as e: logging.error(f"Error moving horizontal servo: {e}")
        return self.pos_h

    def move_to_vz(self, pos):
        try:
            self.servo_v.position = pos
            self.pos_v = pos
            return self._get_pos("v", pos)
        except Exception as e: logging.error(f"Error moving vertical servo: {e}")
        return self.pos_v

