        return self.move_to_hz(pos)

    def move_to_vl(self, pos):
        return self.move_to_vz(pos)

    def move_to_dr(self, pos):
        return self.move_to_hl(pos)

    def move_to_dl(self, pos):
        return self.move_to_vl(pos)

    def move_to_cr(self, pos):
        return self.move_to_hr(pos)

    def turn_on_laser(self):
        self.laser.on()
        self.path.append('e')

    def turn_off_laser(self):
        self.laser.off()
        self.path.append('o')

    def clear(self):
        self.path = []
        logging.info("Path cleared")

    def back(self):
        if self.path: self.path.pop()
        logging.info("Moved back")

    def home(self):
        self.servo_h.position = 0
        self.servo_v.position = 0
        self.pos_h = 0
        self.pos_v = 0
        logging.info("Moved home")

    def send(self, cmd):
        if cmd in self._map: self._send(cmd, 1)
        else: logging.warning(f"Unknown command: {cmd}")

if __name__ == '__main__':
    aim = AimingController()
    try:
        while True:
            aim.send()
    except KeyboardInterrupt:
        aim.clear(); aim.turn_off_laser()
        logging.info("Exiting")

