import serial
import time
import os
import signal
import sys

# Constants
UART_PORT = "/dev/serial0"  # Raspberry Pi UART port (e.g., /dev/serial0 or /dev/ttyS0)
BAUD_RATE = 115200
TIMEOUT = 5
RETRY_DELAY = 1
MAX_RETRIES = 3

# Global variable to track program termination
running = True

def signal_handler(sig, frame):
    """Handles termination signals (e.g., Ctrl+C)."""
    global running
    print("\nExiting gracefully...")
    running = False

def _send_command(module, command, delay=RETRY_DELAY, max_retries=MAX_RETRIES):
    """Sends an AT command to the ESP8266 module and reads the response."""
    try:
        with serial.Serial(UART_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            ser.flushInput()
            ser.flushOutput()
            ser.write((command + '\r\n').encode())
            time.sleep(delay)

            response = b""
            timeout_start = time.time()
            while running and ser.in_waiting > 0:
                chunk = ser.read(1024)
                response += chunk
                if time.time() - timeout_start > TIMEOUT:
                    raise TimeoutError("Timeout waiting for response")

            if ser.in_waiting == 0:
                return None

            decoded_response = response.decode('utf-8', errors='ignore').strip()
            if decoded_response == "OK":
                return None
            elif decoded_response == "ERROR":
                return "ERROR"
            elif decoded_response == "FAIL":
                return "FAIL"
            else:
                return decoded_response

    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return f"SERIAL_ERROR: {e}"
    except TimeoutError as e:
        print(f"Timeout error: {e}")
        return f"TIMEOUT_ERROR: {e}"
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return f"ERROR: {e}"


class ESP8266:
    """A class to encapsulate ESP8266 Wi-Fi module interactions using AT commands."""

    def __init__(self):
        """Initializes the ESP8266 object."""
