        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def read_rfid_tag(serial_connection):
    """Reads an RFID tag from the serial port."""
    try:
        data = serial_connection.readline().decode('ascii', errors='replace').strip()
        return data
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None


def log_access_event(tag_id, log_file_path):
    """Logs the access event to a file."""
    try:
        current_time = time.strftime('%Y-%m-%d %H:%M:%S')
        log_entry = f'{current_time} – RFID Tag: {tag_id}\n'
        with open(log_file_path, 'a') as log:
            log.write(log_entry)
        print(f'Access granted for RFID Tag: {tag_id}')
    except IOError as e:
        print(f"Error writing to log file: {e}")


