logging.basicConfig(filename='power_consumption.log', level=logging.INFO,
                    format='%(asctime)s – Power: %(message)s W')

def read_power_data(serial_port):
    """Reads power data from the serial port and logs it."""
    try:
        data = serial_port.readline().decode('ascii', errors='replace').strip()
        if data:
            try:
                power_value = float(data)
                logging.info(f'Power Consumption: {power_value} W')
            except ValueError:
                logging.error(f"Invalid data received: {data}")
    except serial.SerialException as e:
        logging.error(f"Serial communication error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")

def main():
    """Main function to continuously read and log power consumption data."""
    serial_port = None
    try:
        # Open the serial port for the smart energy meter
        serial_port = serial.Serial('/dev/serial0', 9600, timeout=1)
        logging.info("Serial port opened successfully.")

        # Continuously read and log power consumption data
        while True:
            read_power_data(serial_port)
            time.sleep(1)  # Wait for 1 second before the next reading

    except serial.SerialException as e:
        logging.error(f"Failed to open serial port: {e}")
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    finally:
        # Ensure the serial port is closed on exit
        if serial_port:
            serial_port.close()
            logging.info("Serial port closed.")

if __name__ == "__main__":
    main()

