class Item(BaseModel()):
    """Represents a data point or item."""
    id: int
    name: str
    done: bool = False

    @validator("id", pre=True, always=True)
    def item_id_must_be_integer(cls, v: Union[int, None]):
        if v is not None:
            return int(v)
        return 0

    @validator("name", pre=True, always=True)
    def item_name_must_be_string(cls, v: Union[str, None]):
        if v is not None:
            return str(v)
        return ""  # Allow empty string

    @validator("done", pre=True, always=True)
    def item_done_must_be_boolean(cls, v: Union[bool, None]):
        if v is not None:
            return bool(v)
        return False


class DataStore:
    """Manages the in-memory data store and serial communication."""

    def __init__(self, model_path: str = MODEL_PATH, data_file: str = DATA_FILE):
        self.model_path = model_path
        self.data_file = data_file
        self.data: Dict[int, Item] = {}
        self.load_data()
        self.serial_port: Serial = None  # Initialize serial port to None
        self.serial_is_open = False
        self.serial_retries = MAX_SERIAL_RETRIES
        self.serial_retry_delay = SERIAL_RETRY_DELAY

    def load_data(self):
        """Loads data from the JSON file."""
        try:
            with open(self.data_file, 'r') as f:
                loaded: Dict[int, dict] = json.load(f)
                for item_id, item_data in loaded.items():
                    self.data[item_id] = Item(**item_data)
            logging.info(f"Data loaded from {self.data_file}")
        except FileNotFoundError:
            logging.warning(f"Data file not found: {self.data_file}. Starting with empty data.")
            self.save_data()  # Ensure data is created even if file is missing
        except json.JSONDecodeError as e:
            logging.error(f"Error decoding JSON from {self.data_file}: {e}. Starting with empty data.")
            self.save_data()

    def save_data(self):
        """Saves the current data to the JSON file."""
        try:
            data: Dict[int, dict] = {k: item.dict() for k, item in self.data.items()}
            with open(self.data_file, 'w') as f:
                json.dump(data, f, indent=4)
            logging.info(f"Data saved to {self.data_file}")
        except Exception as e:
            logging.error(f"Error saving data to {self.data_file}: {e}")

    def get_unfinished_count(self) -> int:
        """Returns the number of unfinished items."""
        return sum(1 for item in self.data.values() if not item.done)

    def get_next_item(self) -> Union[Item, None]:
        """Returns the next unfinished item, or None if all items are done."""
        return next((item for item in self.data.values() if not item.done), None)

    def get_item_by_id(self, item_id: int) -> Union[Item, None]:
        """Returns an item by its ID."""
        return self.data.get(item_id)

