        self.serial_is_open = False
        self.serial_retries = MAX_SERIAL_RETRIES
        self.serial_retry_delay = SERIAL_RETRY_DELAY

    def load_data(self):
        """Loads data from the JSON file."""
        try:
            with open(self.data_file, 'r') as f:
                loaded: Dict[int, dict] = json.load(f)
                for item_id, item_data in loaded.items():
                    self.data[item_id] = Item(**item_data)
            logging.info(f"Data loaded from {self.data_file}")
        except FileNotFoundError:
            logging.warning(f"Data file not found: {self.data_file}. Starting with empty data.")
            self.save_data()  # Ensure data is created even if file is missing
        except json.JSONDecodeError as e:
            logging.error(f"Error decoding JSON from {self.data_file}: {e}. Starting with empty data.")
            self.save_data()

    def save_data(self):
        """Saves the current data to the JSON file."""
        try:
            data: Dict[int, dict] = {k: item.dict() for k, item in self.data.items()}
            with open(self.data_file, 'w') as f:
                json.dump(data, f, indent=4)
