            self.data[item_id] = item
        else:
            raise HTTPException(status_code=404, detail="Item not found")

    def delete_item(self, item_id: int):
        """Deletes an item from the data store."""
        if item_id in self.data:
            del self.data[item_id]
        else:
            raise HTTPException(status_code=404, detail="Item not found")

