    def open_serial_port(self):
        """Opens the serial port."""
        if self.serial_port is None or not self.serial_is_open:
            for i in range(self.serial_retries):
                try:
                    self.serial_port = Serial(SERIAL_PORT, baudrate=SERIAL_BAUDRATE, timeout=1)
                    self.serial_port.flush()
                    self.serial_is_open = True
                    logging.info(f"Serial port {SERIAL_PORT} opened successfully.")
                    return True
                except SerialException as e:
                    logging.warning(f"Failed to open serial port {SERIAL_PORT} (attempt {i+1}/{self.serial_retries}): {e}")
                    if i < self.serial_retries - 1:
                        time.sleep(self.serial_retry_delay)
                    else:
                        logging.error(f"Max serial retries reached for port {SERIAL_PORT}.")
                        return False
        return True  # Port already open

    def close_serial_port(self):
        """Closes the serial port."""
        if self.serial_port and self.serial_is_open:
            try:
                self.serial_port.close()
                self.serial_port = None
                self.serial_is_open = False
                logging.info("Serial port closed.")
