import serial
import time

def send_command(command, device):
    """Sends a command over the Bluetooth device."""
    try:
        api_process = serial.Serial(device, 38400)
        full_command = 'X' + command + '\n'
        api_process.write(full_command.encode())
        api_process.close()
        return full_command
    except Exception as e:
        raise RuntimeError(f"Error sending command: {e}")

def main():
    """Main function to continuously prompt for commands."""
    try:
        while True:
            user_input = input("Enter command (or 'exit'): ")
            if user_input.lower() == "exit":
                break
            command_string = send_command(user_input, '/dev/rfcomm4')
            print(f"Sent: {command_string.strip()}")
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nExiting program.")
    except RuntimeError as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()

